/* ============================================================
   Part 107 Quiz — question bank (single source of truth)
   Topics: regulations(31) airspace(28) weather(15)
           loading-performance(10) operations(26)
           night-operations(7) remote-id(8)  = 125 questions
   Strict JSON inside (tools/qc_bank.py parses it).
   All content original, based on public FAA source material:
   14 CFR Part 107, Remote Pilot ACS (FAA-S-ACS-10), FAA study guides.
   QC gates: balanced answer keys, no length tells, no dupes.
   ============================================================ */
window.P107_BANK = [
{"id":"reg-01","topic":"regulations","q":"Under Part 107, a small unmanned aircraft must weigh less than how much at takeoff, including everything on board or attached to it?","options":["25 pounds","55 pounds","75 pounds","100 pounds, including any attached payload"],"answer":1,"exp":"Part 107 applies to small unmanned aircraft weighing less than 55 lb (25 kg) at takeoff, including all payload and anything attached.","ref":"14 CFR 107.3"},
{"id":"reg-02","topic":"regulations","q":"What is the maximum altitude you may fly a small UA under Part 107, unless you stay within 400 feet of a structure?","options":["400 ft AGL","500 ft AGL","400 ft MSL, regardless of terrain elevation","1,200 ft AGL"],"answer":0,"exp":"The ceiling is 400 ft above ground level. You may go higher only within a 400-ft radius of a structure, and then no more than 400 ft above the structure's top.","ref":"14 CFR 107.51(b)"},
{"id":"reg-03","topic":"regulations","q":"What is the maximum groundspeed allowed for a small unmanned aircraft under Part 107?","options":["87 mph","100 mph (87 knots)","120 mph when operating in Class G airspace","55 knots"],"answer":1,"exp":"The groundspeed limit is 100 mph, which equals 87 knots. Remember it is groundspeed, not airspeed, so a tailwind counts against you.","ref":"14 CFR 107.51(a)"},
{"id":"reg-04","topic":"regulations","q":"What is the minimum age to hold a remote pilot certificate with an sUAS rating?","options":["18 years old","14 years old","16 years old","21 years old"],"answer":2,"exp":"You must be at least 16 years old to be eligible for a remote pilot certificate.","ref":"14 CFR 107.61"},
{"id":"reg-05","topic":"regulations","q":"To keep exercising the privileges of a remote pilot certificate, how often must you complete recurrent training?","options":["Every 12 calendar months","Every 36 calendar months","Only once, before the initial knowledge test","Every 24 calendar months"],"answer":3,"exp":"Recurrent training (free, online) must be completed within the previous 24 calendar months to operate under Part 107. The certificate itself does not expire.","ref":"14 CFR 107.65"},
{"id":"reg-06","topic":"regulations","q":"How soon must you report a qualifying sUAS accident to the FAA?","options":["Immediately by phone","Within 24 hours","Within 10 calendar days","Within 30 calendar days of the event"],"answer":2,"exp":"A report is required no later than 10 calendar days after an operation that causes serious injury, loss of consciousness, or qualifying property damage.","ref":"14 CFR 107.9"},
{"id":"reg-07","topic":"regulations","q":"Which event requires an accident report to the FAA under Part 107?","options":["Any damage to any property, no matter how small the cost","Serious injury, or at least $500 damage to property other than the drone","Only an accident involving a fatality","Damage to the drone itself costing more than $500 to repair"],"answer":1,"exp":"Report when there is serious injury or loss of consciousness, or repair/replacement of damaged property OTHER than the UA costs $500 or more.","ref":"14 CFR 107.9"},
{"id":"reg-08","topic":"regulations","q":"What is the minimum time that must pass between consuming alcohol and operating a small UA ('bottle to throttle')?","options":["12 hours","4 hours","24 hours","8 hours"],"answer":3,"exp":"No one may act as a crewmember within 8 hours of consuming alcohol, while under its influence, or with a blood alcohol concentration of .04 or greater.","ref":"14 CFR 107.27, 91.17"},
{"id":"reg-09","topic":"regulations","q":"A person may not operate an sUAS with a blood alcohol concentration at or above what level?","options":["0.08","0.02","0.04","0.10"],"answer":2,"exp":"The limit that applies to airmen, including remote pilots, is .04 BAC — stricter than the typical .08 driving limit.","ref":"14 CFR 107.27, 91.17"},
{"id":"reg-10","topic":"regulations","q":"What does it cost to register a drone for Part 107 operations, and how long is the registration valid?","options":["$5 per aircraft, valid 3 years","$5 per pilot for all aircraft, valid 1 year","Free, valid forever","$25 per aircraft, valid 3 years"],"answer":0,"exp":"Part 107 registration in FAA DroneZone is $5 per aircraft and lasts 3 years. The registration number must be marked on the outside of the aircraft.","ref":"14 CFR Part 48"},
{"id":"reg-11","topic":"regulations","q":"Upon request, the remote pilot in command must present the remote pilot certificate to which of the following?","options":["Only FAA aviation safety inspectors conducting a formal ramp inspection at the flight site","The FAA, NTSB, TSA, or any federal, state, or local law enforcement officer","Airport managers within 5 NM","Insurance company adjusters"],"answer":1,"exp":"107.7 requires presenting the certificate and identification on request to the FAA, NTSB, TSA, or law enforcement.","ref":"14 CFR 107.7"},
{"id":"reg-12","topic":"regulations","q":"During an in-flight emergency, what deviation authority does the remote pilot in command have?","options":["None — the rules always apply","May deviate from any Part 107 rule to the extent required to meet the emergency, and must send a written report if the FAA requests one","May deviate only after getting ATC approval by radio","May deviate only below 200 ft AGL"],"answer":1,"exp":"In an emergency requiring immediate action, the RPIC may deviate from any rule of Part 107 to the extent needed. The FAA may request a written report afterward.","ref":"14 CFR 107.21"},
{"id":"reg-13","topic":"regulations","q":"Without a waiver, how many small unmanned aircraft may one remote pilot operate at the same time?","options":["One","Two, with a visual observer","Three, if all are under 2 lb","As many as the pilot can safely watch"],"answer":0,"exp":"A person may manipulate the controls of, or act as RPIC for, only one UA at a time unless the FAA has granted a 107.35 waiver.","ref":"14 CFR 107.35"},
{"id":"reg-14","topic":"regulations","q":"Under Part 107, carrying hazardous materials on a small unmanned aircraft is:","options":["Allowed with proper placards","Allowed if the total weight stays under 55 lb","Prohibited","Allowed only over unpopulated areas"],"answer":2,"exp":"107.36 flatly prohibits the carriage of hazardous materials (as defined in 49 CFR 171.8), including spare lithium batteries carried as cargo.","ref":"14 CFR 107.36"},
{"id":"reg-15","topic":"regulations","q":"A small unmanned aircraft must yield the right of way to:","options":["All other aircraft","Only manned aircraft in distress","Only aircraft below 400 ft AGL","Only other unmanned aircraft"],"answer":0,"exp":"The sUAS must yield to ALL aircraft, airborne vehicles, and launch/reentry vehicles, and may not pass over, under, or ahead of them unless well clear.","ref":"14 CFR 107.37"},
{"id":"reg-16","topic":"regulations","q":"Operating a small UA from a moving land vehicle is permitted only:","options":["Never, under any circumstances","Anywhere, as long as groundspeed stays under 100 mph","Over a sparsely populated area, and not transporting property for compensation","At night with anti-collision lighting"],"answer":2,"exp":"107.25 allows operating from a moving land or water vehicle only over sparsely populated areas, and never while transporting property for compensation or hire. Operating from a moving aircraft is always prohibited.","ref":"14 CFR 107.25"},
{"id":"reg-17","topic":"regulations","q":"Dropping material from a small unmanned aircraft in flight is:","options":["Always prohibited","Allowed only with a Part 107 waiver approved through the FAA DroneZone portal","Allowed only over your own property","Allowed if it creates no undue hazard to people or property"],"answer":3,"exp":"107.23 prohibits allowing an object to be dropped in a way that creates an undue hazard. A safe, controlled drop over a clear area is not itself illegal.","ref":"14 CFR 107.23"},
{"id":"reg-18","topic":"regulations","q":"Before each flight, the remote pilot in command must:","options":["Inspect the sUAS to ensure it is in a condition for safe operation","File a flight plan with the FAA at least 24 hours before launch","Notify the nearest control tower","Log the flight in IACRA"],"answer":0,"exp":"107.49 requires a preflight check of the aircraft, control links, power supply, and the operating environment before every flight.","ref":"14 CFR 107.49"},
{"id":"reg-19","topic":"regulations","q":"A person who does NOT hold a remote pilot certificate may fly the controls of an sUAS only if:","options":["They are at least 16 years old","They have completed the TRUST test","A visual observer is watching the aircraft","A remote pilot in command directly supervises them and can take immediate control"],"answer":3,"exp":"Non-certificated persons may manipulate the controls only under the direct supervision of an RPIC who is able to take immediate control of the aircraft.","ref":"14 CFR 107.12, 107.19"},
{"id":"reg-20","topic":"regulations","q":"Who is directly responsible for, and the final authority on, the operation of a small unmanned aircraft system?","options":["The drone's registered owner","The visual observer","The remote pilot in command","The client who hired the flight"],"answer":2,"exp":"The RPIC is directly responsible for and is the final authority as to the operation of the sUAS.","ref":"14 CFR 107.19"},
{"id":"reg-21","topic":"regulations","q":"How do you obtain authorization to operate in controlled airspace under Part 107?","options":["From the airport manager","From local law enforcement","Through LAANC or the FAA DroneZone","No authorization is needed if you stay below 400 ft"],"answer":2,"exp":"Prior authorization for Class B, C, D, or surface Class E airspace comes from the FAA — in practice through LAANC for near-real-time approval, or DroneZone where LAANC is unavailable.","ref":"14 CFR 107.41"},
{"id":"reg-22","topic":"regulations","q":"Which of the following operations requires a remote pilot certificate under Part 107?","options":["Flying for fun in your backyard","Flying a drone indoors at home","A recreational park flight after completing TRUST","Photographing a house for a realtor's listing"],"answer":3,"exp":"Any flight that furthers a business purpose — like real-estate photography — is non-recreational and requires Part 107 certification.","ref":"14 CFR 107.1"},
{"id":"reg-23","topic":"regulations","q":"Refusing to submit to a lawful drug or alcohol test can result in:","options":["Denial of an application, or suspension or revocation of the remote pilot certificate","A written warning only","A mandatory retest within 30 days","No consequence under Part 107"],"answer":0,"exp":"Refusal to submit to testing is grounds for denying a certificate application for up to one year, or suspending/revoking the certificate.","ref":"14 CFR 107.57, 107.59"},
{"id":"reg-24","topic":"regulations","q":"Which statement about visual observers (VOs) under Part 107 is true?","options":["A VO is required for every commercial flight","VOs must hold their own remote pilot certificate","Using a VO is optional, and it does not remove the see-and-avoid responsibilities of the RPIC","A VO may watch the aircraft through binoculars full-time"],"answer":2,"exp":"VOs are optional crew. Even with a VO, the RPIC and person flying must still be able to see the aircraft and maintain awareness; vision aids like binoculars may only be used momentarily.","ref":"14 CFR 107.31, 107.33"},
{"id":"reg-25","topic":"regulations","q":"A client wants footage of an antenna tower that stands 700 ft tall. Staying within 400 ft of the structure, how high may you legally fly?","options":["Up to 1,100 ft AGL","Up to 400 ft AGL, because the Part 107 ceiling has no exception for tall structures","Up to 700 ft AGL, matching the height of the structure you are inspecting","Any altitude at all, as long as you remain within a 400-ft radius of the tower"],"answer":0,"exp":"Within a 400-ft radius of a structure you may fly up to 400 ft above that structure's uppermost limit, so 700 + 400 = 1,100 ft AGL. Step outside the radius and the plain 400-ft ceiling applies again.","ref":"14 CFR 107.51(b)"},
{"id":"reg-26","topic":"regulations","q":"You are hired to film a parade, and cars carrying people are moving along the route beneath your planned flight path. Under Part 107:","options":["flight over moving vehicles is unrestricted as long as you remain above 100 ft AGL","flight over moving vehicles is always prohibited, and no category of aircraft changes that","you may overfly the vehicles if every occupant consented to the operation in writing beforehand","sustained flight over moving vehicles requires an eligible category aircraft"],"answer":3,"exp":"107.145 permits operations over moving vehicles only with a Category 1-4 eligible aircraft, and outside a closed or restricted site the flight must be a transit rather than sustained loitering overhead.","ref":"14 CFR 107.145, 107.39"},
{"id":"reg-27","topic":"regulations","q":"Your drone weighs 0.9 lb and you fly it only for paid real-estate photography. Registration is:","options":["not required, because registration applies only to aircraft heavier than 55 lb","required only after you have completed your first ten paid jobs with that aircraft","required — $5 per aircraft, marked on the exterior","handled automatically by the manufacturer when the aircraft is first activated in its companion app"],"answer":2,"exp":"Under Part 107 every aircraft must be registered regardless of weight; the 250 g threshold applies only to recreational flying. Registration costs $5 per aircraft, lasts 3 years, and the number must be legible on the exterior.","ref":"14 CFR Part 48; 14 CFR 107.13"},
{"id":"reg-28","topic":"regulations","q":"A treeline will hide the aircraft from you for roughly 20 seconds during a planned route. Your lawful options are to:","options":["fly the route and rely on the live video feed while the aircraft is behind the trees","reroute to keep the aircraft in sight, or hold a 107.31 waiver","station a visual observer behind the treeline and continue, since the observer preserves line of sight","climb above 400 ft AGL for that segment so the aircraft stays visible over the trees"],"answer":1,"exp":"Visual line of sight must be maintained by the RPIC or the person manipulating the controls, unaided by anything but corrective lenses. A video feed does not satisfy it and a distant observer cannot substitute for it.","ref":"14 CFR 107.31, 107.33, 107.205"},
{"id":"reg-29","topic":"regulations","q":"Your recurrent training lapsed six weeks ago, and today a client asks for a paid flight. You may:","options":["not fly under Part 107 until you complete the recurrent training","fly, because the remote pilot certificate itself never expires","fly under the supervision of any other certificated remote pilot for up to 90 days","fly, provided you retake and pass the initial knowledge test at a testing center within 30 days"],"answer":0,"exp":"The certificate does not expire, but its privileges lapse unless recurrent training was completed within the previous 24 calendar months. The free online course takes under an hour and restores the privileges immediately.","ref":"14 CFR 107.65"},
{"id":"reg-30","topic":"regulations","q":"A paid shoot in Class G airspace will run until 45 minutes after official sunset. The flight is legal if:","options":["the aircraft remains below 200 ft AGL for the entire post-sunset portion","a visual observer on site also holds a remote pilot certificate","the operation was filed as a night waiver in DroneZone at least 90 days in advance","the aircraft has anti-collision lighting visible for 3 statute miles"],"answer":3,"exp":"Night flight is a standard privilege for pilots whose knowledge test or recurrent training covered night operations. The remaining hard requirement is anti-collision lighting visible for 3 SM with an adequate flash rate.","ref":"14 CFR 107.29"},
{"id":"reg-31","topic":"regulations","q":"Which Part 107 rule may NOT be waived by the FAA?","options":["The 400-ft altitude limit","The visual line of sight requirement","The restriction on operating from a moving vehicle over other than sparsely populated areas","The prohibition on carrying hazardous materials"],"answer":3,"exp":"107.205 lists the sections the FAA may waive, including altitude, visual line of sight, and operations over people. The hazardous materials prohibition in 107.36 is absent from that list and can never be waived.","ref":"14 CFR 107.205, 107.36"},
{"id":"air-01","topic":"airspace","q":"What ATC authorization is required to fly a small UA in Class G airspace?","options":["LAANC authorization","A DroneZone waiver","Verbal approval from the nearest tower","None — Class G is uncontrolled airspace"],"answer":3,"exp":"Class G is uncontrolled; no airspace authorization is required there under Part 107. All other operating rules still apply.","ref":"14 CFR 107.41"},
{"id":"air-02","topic":"airspace","q":"On a VFR sectional chart, a dashed blue line around an airport depicts which airspace?","options":["Class B","Class C","Class D","Class E at the surface"],"answer":2,"exp":"Class D airspace (smaller towered airports) is charted with a dashed blue line, typically from the surface to about 2,500 ft AGL.","ref":"Remote Pilot ACS UA.II; sectional legend"},
{"id":"air-03","topic":"airspace","q":"Solid magenta lines on a sectional chart depict which airspace class?","options":["Class B","Class C","Class D","Surface Class E"],"answer":1,"exp":"Class C — mid-size towered airports with radar services — is depicted with solid magenta rings (typically a 5-NM core plus an outer shelf).","ref":"Sectional chart legend"},
{"id":"air-04","topic":"airspace","q":"Solid blue lines on a sectional chart depict which airspace class?","options":["Class B","Class C","Class D","Class G uncontrolled airspace"],"answer":0,"exp":"Class B surrounds the busiest airports and is charted with solid blue lines, usually as stacked shelves like an upside-down wedding cake.","ref":"Sectional chart legend"},
{"id":"air-05","topic":"airspace","q":"A dashed magenta line around an airport indicates:","options":["Class C airspace","Class E airspace beginning at the surface","Class D airspace","A military operations area with active training routes"],"answer":1,"exp":"Dashed magenta = surface Class E. It is controlled airspace at ground level, so drone flights there need FAA authorization.","ref":"Sectional chart legend"},
{"id":"air-06","topic":"airspace","q":"Which airspace classes require ATC authorization before a Part 107 flight?","options":["Only Class B","Class B and C only","Class B, C, D, and surface Class E","All airspace classes, including uncontrolled Class G"],"answer":2,"exp":"Controlled airspace for drones means B, C, D, and the surface areas of Class E. Class G needs no authorization.","ref":"14 CFR 107.41"},
{"id":"air-07","topic":"airspace","q":"The fuzzy magenta shading (vignette) on a sectional chart shows:","options":["Class E airspace beginning at 700 ft AGL","Class E airspace at the surface","A restricted area boundary","Class G airspace above 1,200 ft AGL in that area"],"answer":0,"exp":"Inside the magenta vignette, Class E starts at 700 ft AGL (elsewhere it generally starts at 1,200 ft). Drones below 400 ft rarely touch it — but surface Class E is different.","ref":"Sectional chart legend"},
{"id":"air-08","topic":"airspace","q":"An area charted as 'P-56' is:","options":["A practice area reserved for student pilot training flights","A prohibited area where flight is not allowed","A parachute drop zone","A Class E extension"],"answer":1,"exp":"'P' plus a number designates a prohibited area (P-56 covers the White House and National Mall area). Drone flight there is prohibited.","ref":"Remote Pilot ACS UA.II; chart legend"},
{"id":"air-09","topic":"airspace","q":"Restricted areas (charted 'R-' plus a number) typically contain what kind of hazard?","options":["Parachute jumping activity only","Wildlife sanctuaries","Hazards such as artillery firing, aerial gunnery, or guided missiles","High volumes of student pilot training"],"answer":2,"exp":"Restricted areas hold invisible hazards to aircraft. When active, entry requires permission from the controlling agency.","ref":"Chart legend; FAA Remote Pilot Study Guide"},
{"id":"air-10","topic":"airspace","q":"What does a Military Operations Area (MOA) mean for a small UA pilot?","options":["Drone flight is prohibited at all times","Military training occurs there — flight is not prohibited, but exercise extreme caution","LAANC authorization is mandatory","Only military drones may fly"],"answer":1,"exp":"MOAs separate military training from IFR traffic. Drones are not banned, but fast low-flying military aircraft demand extra vigilance.","ref":"FAA Remote Pilot Study Guide"},
{"id":"air-11","topic":"airspace","q":"Where would you find current information about a Temporary Flight Restriction (TFR)?","options":["The sectional chart legend","METAR reports","NOTAMs","The Chart Supplement"],"answer":2,"exp":"TFRs are issued and updated through Notices to Air Missions (NOTAMs). Sectionals are printed too infrequently to show them.","ref":"FAA Remote Pilot Study Guide"},
{"id":"air-12","topic":"airspace","q":"The Maximum Elevation Figure (MEF) printed in each quadrant of a sectional chart represents:","options":["The height above ground of the tallest man-made obstacle in that quadrant, in feet AGL","The elevation of the highest terrain or obstacle in that quadrant, in feet MSL","The airport field elevation","The maximum altitude for drone operations"],"answer":1,"exp":"MEF gives the highest known feature in the quadrangle, rounded up, in thousands and hundreds of feet MSL.","ref":"Sectional chart legend"},
{"id":"air-13","topic":"airspace","q":"An MEF shown as a large '2' with a small '3' means the highest feature in that quadrant is approximately:","options":["230 ft MSL","2,300 ft AGL","23,000 ft MSL","2,300 ft MSL"],"answer":3,"exp":"Read MEF as thousands then hundreds of feet MSL: 2 and 3 = 2,300 ft MSL.","ref":"Sectional chart legend"},
{"id":"air-14","topic":"airspace","q":"An airport symbol printed in magenta on a sectional chart tells you the airport:","options":["Has an operating control tower","Is a military field with prior-permission-required rules","Does not have an operating control tower","Is closed to all traffic"],"answer":2,"exp":"Blue airports are towered; magenta airports are non-towered. Near magenta airports, monitor the CTAF for traffic awareness.","ref":"Sectional chart legend"},
{"id":"air-15","topic":"airspace","q":"Next to an airport, the sectional chart shows 'CT - 118.3'. What does this mean?","options":["The control tower frequency is 118.3","The field elevation is 1,183 ft MSL","The CTAF is unavailable at this field","Runway 11/83 is in use"],"answer":0,"exp":"'CT' identifies the control tower frequency. Monitoring it (or the CTAF at non-towered fields) builds situational awareness about nearby manned traffic.","ref":"Sectional chart legend"},
{"id":"air-16","topic":"airspace","q":"The standing stadium TFR restricts flight near major sporting events within what radius and time window?","options":["5 NM radius, all day on game day","10 NM radius during the event","1 NM radius, during the event only","3 NM radius, from 1 hour before until 1 hour after the event"],"answer":3,"exp":"Flights are restricted within 3 NM of qualifying stadium events (MLB, NFL, NCAA Division I football, major races) from one hour before to one hour after.","ref":"FDC NOTAM 4/3621 (stadium TFR)"},
{"id":"air-17","topic":"airspace","q":"Part 107 requires that operations near an airport must not:","options":["Interfere with airport operations or traffic patterns","Occur within 5 NM under any circumstances","Occur without a radio call on the CTAF","Occur without the airport manager's prior written approval on file"],"answer":0,"exp":"107.43 prohibits interfering with operations and traffic patterns at any airport, heliport, or seaplane base. In Class G near an airport you may fly, but must stay clear of traffic.","ref":"14 CFR 107.43"},
{"id":"air-18","topic":"airspace","q":"Lines of longitude on aeronautical charts:","options":["Run east-west around the globe and measure angular distance north or south of the equator","Run north-south and are measured east or west of the Prime Meridian","Run parallel to the equator","Exist only in the Northern Hemisphere"],"answer":1,"exp":"Meridians of longitude run pole to pole and are measured 0-180° east or west from Greenwich. Latitude lines run east-west, measured from the equator.","ref":"FAA Remote Pilot Study Guide"},
{"id":"air-19","topic":"airspace","q":"An obstacle on a sectional chart shows a bold number with a second number in parentheses. These represent:","options":["Both heights above ground level","The bold figure is height AGL; the figure in parentheses is MSL","Both heights above mean sea level","Bold is MSL; the number in parentheses is AGL"],"answer":3,"exp":"The bold figure is the obstacle top in feet MSL; the parenthetical figure is its height AGL. Useful for judging clearance from your launch elevation.","ref":"Sectional chart legend"},
{"id":"air-20","topic":"airspace","q":"Which statement about LAANC is correct?","options":["It guarantees separation from manned traffic","It files a flight plan for you","It provides near-real-time authorization up to the published UAS Facility Map ceiling","It replaces aircraft registration"],"answer":2,"exp":"LAANC issues automated authorizations for controlled airspace up to the grid ceiling shown on UAS Facility Maps. Seeing and avoiding traffic remains your job.","ref":"14 CFR 107.41; FAA LAANC guidance"},
{"id":"air-21","topic":"airspace","q":"A dashed blue line encircles an airport 4 NM from your job site, and a boxed [25] sits inside the ring. You plan to fly at 300 ft AGL from a park inside that ring. What is required?","options":["Nothing — the [25] means that airspace begins at 2,500 ft MSL, far above your planned altitude","A written waiver from the airport manager before each flight conducted inside the ring","Only a NOTAM filed with Flight Service at least one hour before you launch the aircraft","FAA airspace authorization, normally through LAANC"],"answer":3,"exp":"The boxed number is the Class D CEILING in hundreds of feet MSL (2,500 ft), not a floor. Class D extends down to the surface, so any Part 107 flight inside the dashed blue ring needs prior FAA authorization.","ref":"14 CFR 107.41; sectional chart legend"},
{"id":"air-22","topic":"airspace","q":"Your launch site sits under the faded magenta vignette but outside any dashed line. You will fly at 350 ft AGL. What authorization do you need?","options":["None — you are in Class G below 700 ft AGL","LAANC authorization for surface Class E, which the vignette depicts around every non-towered airport","A 107.41 waiver through FAA DroneZone, because the vignette marks controlled airspace at the surface","Verbal permission from the nearest control tower on the CTAF frequency"],"answer":0,"exp":"The fuzzy magenta vignette marks where Class E begins at 700 ft AGL. Below that floor the airspace is Class G, so no authorization is required. It is the dashed magenta line, not the vignette, that marks surface Class E.","ref":"Sectional chart legend; 14 CFR 107.41"},
{"id":"air-23","topic":"airspace","q":"The UAS Facility Map grid covering your site inside Class D airspace reads 0. This means:","options":["LAANC is unavailable in that county, so you may fly there without any authorization","You may fly up to 100 ft AGL, because grid values are published in hundreds of feet","The airspace is closed to all aircraft, both manned and unmanned, until further notice","No LAANC auto-approval — request authorization through DroneZone"],"answer":3,"exp":"A 0-ft grid means the FAA has pre-approved no altitude at that location. LAANC will reject the request, so authorization must go through the DroneZone further-coordination process, which can take up to 90 days.","ref":"FAA UAS Facility Maps; 14 CFR 107.41"},
{"id":"air-24","topic":"airspace","q":"Directly above your site, the Class B chart segment reads 100/40. That tells you Class B in that sector:","options":["runs from 4,000 ft MSL up to 10,000 ft MSL","runs from 4,000 ft AGL up to 10,000 ft AGL, measured from the ground directly beneath you","extends from the surface up to 10,000 ft MSL and has a 40 NM outer ring","applies only to aircraft heavier than 10,000 lb operating above 4,000 ft"],"answer":0,"exp":"Class B shelves are charted as ceiling over floor in hundreds of feet MSL, so 100/40 is a 4,000 ft MSL floor and a 10,000 ft MSL ceiling. Below the shelf floor you are not in Class B, but always check for a surface area nearby.","ref":"Sectional chart legend"},
{"id":"air-25","topic":"airspace","q":"A non-towered airport 2 NM away is ringed by a dashed magenta line. You intend to fly at 200 ft AGL inside that ring. You must:","options":["self-announce your intentions on the CTAF before every takeoff and every landing","stay at or below 400 ft AGL, which is all that Part 107 asks of you at that location","notify the airport operator in writing at least 24 hours before the planned flight","obtain FAA airspace authorization before flying"],"answer":3,"exp":"A dashed magenta line is Class E beginning at the surface — controlled airspace at ground level. Your altitude is irrelevant; any Part 107 flight inside that boundary needs prior FAA authorization.","ref":"14 CFR 107.41; sectional chart legend"},
{"id":"air-26","topic":"airspace","q":"Your site falls inside an area charted as 'A-211'. For a Part 107 pilot this means:","options":["Flight is prohibited at all times unless the using agency grants written permission in advance","Heavy pilot training may occur there; no authorization is needed, but stay vigilant","The area is a Temporary Flight Restriction that will expire within 24 hours of activation","The airspace is Class A, so Part 107 operations are not possible at that location"],"answer":1,"exp":"Alert Areas (the A- prefix) flag a high volume of pilot training or unusual aerial activity. They impose no entry restriction on Part 107 flights, but manned traffic there can be dense and unpredictable.","ref":"AIM 3-4-6; sectional chart legend"},
{"id":"air-27","topic":"airspace","q":"An airport data block on the sectional reads: RIVERTON (RVT) 53 L 72 122.8. The 72 means:","options":["the longest runway is about 7,200 ft","the field elevation is 7,200 ft above mean sea level at the airport reference point","the recommended traffic pattern altitude at that field is 720 ft above ground level","the airport currently has 72 based aircraft on the field"],"answer":0,"exp":"An airport data block runs elevation, lighting, then longest runway length in hundreds of feet. Here 53 is the field elevation, L means lighting is available, 72 is a 7,200 ft runway, and 122.8 is the CTAF.","ref":"Sectional chart legend"},
{"id":"air-28","topic":"airspace","q":"Two hours before a scheduled roof inspection you learn that a VIP TFR now covers the site. You should:","options":["fly anyway below 200 ft AGL, since TFRs restrict only manned aircraft above 500 ft","call local law enforcement and request a spot exemption for a short commercial flight","launch immediately, before the effective time published in the NOTAM takes hold","cancel or reschedule the flight"],"answer":3,"exp":"TFRs apply to unmanned aircraft too, and violating one risks certificate action plus federal penalties. No local authority can waive a TFR, so reschedule and re-check NOTAMs or B4UFLY before every flight.","ref":"14 CFR 91.137-91.145; FAA NOTAM guidance"},
{"id":"wx-01","topic":"weather","q":"What is the minimum flight visibility for Part 107 operations?","options":["1 statute mile","3 statute miles from the control station","5 statute miles","There is no visibility minimum for sUAS operations below 400 ft"],"answer":1,"exp":"Minimum visibility, as observed from the control station, is 3 statute miles.","ref":"14 CFR 107.51(c)"},
{"id":"wx-02","topic":"weather","q":"What minimum distance must a small UA keep from clouds?","options":["500 ft below and 2,000 ft horizontally","1,000 ft above and 1 statute mile horizontally","2,000 ft below and 500 ft horizontally","Simply remain clear of clouds"],"answer":0,"exp":"Stay at least 500 ft below and 2,000 ft horizontally from any cloud — so a manned aircraft popping out of the cloud has room to be seen and avoided.","ref":"14 CFR 107.51(d)"},
{"id":"wx-03","topic":"weather","q":"In the METAR 'KAUS 121853Z 24015G25KT 10SM SCT045 32/18 A2992', what does '24015G25KT' mean?","options":["Wind blowing toward 240° at 15 knots","Wind from 240° true at 15 knots, gusting to 25 knots","Wind from 150° at 24 knots, gusting 25","Variable wind at 15 knots"],"answer":1,"exp":"First three digits are the direction the wind is FROM (240° true); next two are speed (15 kt); G25 = gusts to 25 kt.","ref":"FAA Aviation Weather Services concepts"},
{"id":"wx-04","topic":"weather","q":"In a METAR, 'A2992' indicates:","options":["Temperature of 29.92°C","The altimeter setting is 29.92 inHg","Wind from 299° at 2 knots","The pressure altitude at the field is 2,992 ft"],"answer":1,"exp":"'A' precedes the altimeter setting in inches of mercury — here 29.92, which happens to be the standard-atmosphere value.","ref":"FAA Aviation Weather Services concepts"},
{"id":"wx-05","topic":"weather","q":"A TAF is best described as:","options":["An hourly surface observation of the current weather at an airport","A forecast for the area within 5 statute miles of an airport","A national radar summary","A winds-aloft chart"],"answer":1,"exp":"A Terminal Aerodrome Forecast covers expected conditions within 5 SM of the airport, typically for 24 or 30 hours. METARs are the current observations.","ref":"FAA Aviation Weather Services concepts"},
{"id":"wx-06","topic":"weather","q":"How does HIGH density altitude affect a multirotor drone?","options":["Rotor efficiency improves","Battery endurance increases","Rotor/propeller efficiency and overall performance decrease","It has no measurable performance effect below 400 ft AGL"],"answer":2,"exp":"Hot, high, and humid conditions thin the air. Props produce less thrust, motors work harder, and endurance drops.","ref":"FAA Remote Pilot Study Guide; PHAK ch. 11 concepts"},
{"id":"wx-07","topic":"weather","q":"What are the standard atmosphere values at sea level?","options":["15°C (59°F) and 29.92 inHg","0°C (32°F) and 30.00 inHg at all latitudes","21°C (70°F) and 29.92 inHg","15°C (59°F) and 30.12 inHg"],"answer":0,"exp":"Standard sea-level atmosphere is 15°C / 59°F and 29.92 inHg — the baseline for density-altitude calculations.","ref":"PHAK ch. 4 concepts"},
{"id":"wx-08","topic":"weather","q":"Which conditions are characteristic of STABLE air?","options":["Cumulus clouds and good visibility","Stratiform clouds, smooth air, and poor visibility","Showery precipitation and turbulence","Towering thunderstorms"],"answer":1,"exp":"Stable air resists vertical motion: layered stratus clouds, smooth flying, steady precipitation, and haze trapped low (poor visibility).","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-09","topic":"weather","q":"Which conditions are characteristic of UNSTABLE air?","options":["Steady drizzle and fog","Stratus layers and haze","Cumulus clouds, showery precipitation, turbulence, and good visibility","Temperature inversions"],"answer":2,"exp":"Unstable air rises freely: puffy cumulus, showers, bumpy air — but the vertical mixing sweeps haze out, so visibility is good.","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-10","topic":"weather","q":"What three ingredients are required for a thunderstorm to form?","options":["Moisture, unstable air, and a lifting force","High pressure, cold temperatures, and strong wind","Stratus clouds, drizzle, and wind shear","A temperature inversion, moisture, and calm air"],"answer":0,"exp":"Water vapor, an unstable lapse rate, and initial lift (fronts, terrain, heating) are the classic recipe.","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-11","topic":"weather","q":"The MATURE stage of a thunderstorm begins when:","options":["Updrafts first develop in the cumulus stage","The anvil top forms","Lightning first appears","Precipitation begins falling at the surface"],"answer":3,"exp":"Rain reaching the surface marks the mature stage — the storm's most violent phase, with simultaneous updrafts and downdrafts.","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-12","topic":"weather","q":"A microburst is best described as:","options":["A small, short-lived tornado","An updraft inside a cumulus cloud","An intense, localized downdraft from a convective cloud","A gust front ahead of a sea breeze"],"answer":2,"exp":"Microbursts are concentrated downdrafts that spread out violently near the ground — extremely hazardous wind shear for any aircraft, including drones.","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-13","topic":"weather","q":"Radiation fog is most likely to form under which conditions?","options":["A windy afternoon along the coast","Passage of a fast-moving cold front","Strong daytime heating over dry ground","A clear, calm night over moist ground"],"answer":3,"exp":"With clear skies and calm wind, the ground radiates heat away and the moist surface layer cools to its dewpoint — classic valley morning fog.","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-14","topic":"weather","q":"Advection fog forms when:","options":["Moist air moves over a cooler surface","Ground cools rapidly on a calm, clear night","Rain falls into a layer of dry air","Air is forced down a mountain slope"],"answer":0,"exp":"Advection fog needs wind to push moist air across a colder surface — why it is common along coastlines, and it can persist under windier conditions than radiation fog.","ref":"FAA Remote Pilot Study Guide"},
{"id":"wx-15","topic":"weather","q":"The temperature/dewpoint spread is small and decreasing. What should you expect?","options":["Severe clear-air turbulence at the surface is imminent","A rapid drop in density altitude","Fog or low clouds are likely to form","Visibility will improve"],"answer":2,"exp":"When temperature approaches the dewpoint, air is near saturation — fog, mist, or low stratus become likely, threatening your 3-SM visibility minimum.","ref":"FAA Remote Pilot Study Guide"},
{"id":"load-01","topic":"loading-performance","q":"Compared with the same aircraft lightly loaded, a heavily loaded multirotor will have:","options":["Longer endurance","Reduced climb performance and shorter endurance","A faster maximum climb rate due to added momentum","No measurable difference"],"answer":1,"exp":"More weight demands more thrust and power, which drains the battery faster and reduces climb margin and gust tolerance.","ref":"FAA Remote Pilot Study Guide; PHAK ch. 10 concepts"},
{"id":"load-02","topic":"loading-performance","q":"Operating with the center of gravity outside the manufacturer's limits is most likely to cause:","options":["Improved maneuverability","Longer flight time","Control difficulties or instability","Nothing, if the aircraft is under 55 lb"],"answer":2,"exp":"CG position outside limits degrades stability and control authority — for camera drones, a badly mounted payload is the usual culprit.","ref":"FAA Remote Pilot Study Guide"},
{"id":"load-03","topic":"loading-performance","q":"Which situation creates the greatest fire risk with lithium polymer (LiPo) batteries?","options":["Storing them at about 50% charge","Storing them in a cool, dry place","Charging with the manufacturer's recommended charger","Physical damage, puncture, or overcharging"],"answer":3,"exp":"Damaged or overcharged LiPo cells can enter thermal runaway. Inspect packs after any hard landing and never charge a swollen or punctured battery.","ref":"FAA Remote Pilot Study Guide; SAFO guidance"},
{"id":"load-04","topic":"loading-performance","q":"The safest guidance for charging sUAS batteries is to:","options":["Follow the manufacturer's charging instructions","Use any USB charger that fits","Always store packs fully charged so they're ready to fly","Charge unattended overnight"],"answer":0,"exp":"Manufacturer procedures govern charge rates, balance charging, and storage voltage — deviating is the most common cause of battery incidents.","ref":"FAA Remote Pilot Study Guide"},
{"id":"load-05","topic":"loading-performance","q":"You launch from a high-elevation site on a hot day. What performance change should you expect?","options":["More thrust available","Reduced thrust and a smaller performance margin","Faster battery charging thanks to the thinner air","Improved GPS accuracy"],"answer":1,"exp":"High and hot means high density altitude: thinner air, less thrust and lift, harder-working motors, and reduced endurance.","ref":"FAA Remote Pilot Study Guide"},
{"id":"load-06","topic":"loading-performance","q":"In a level, coordinated 60° bank turn, the load factor on an aircraft is approximately:","options":["1 g","1.4 g","4 g","2 g"],"answer":3,"exp":"Load factor = 1/cos(bank). At 60° that is 2 g — the structure and lift must support twice the aircraft's weight.","ref":"PHAK ch. 5 concepts"},
{"id":"load-07","topic":"loading-performance","q":"For a fixed-wing sUAS, increasing the load factor causes the stall speed to:","options":["Decrease","Stay the same","Increase","Become irrelevant"],"answer":2,"exp":"Stall speed rises with the square root of load factor — steep turns or abrupt pull-ups can stall a fixed-wing UA well above its normal stall speed.","ref":"PHAK ch. 5 concepts"},
{"id":"load-08","topic":"loading-performance","q":"Exceeding the manufacturer's maximum gross weight risks:","options":["Nothing, provided the overload lasts only a few minutes","Structural overstress and degraded performance","Only a shorter warranty","Better stability in wind"],"answer":1,"exp":"Weight above design limits eats into structural margins and performance — and any payload attached counts toward the 55-lb Part 107 limit too.","ref":"FAA Remote Pilot Study Guide"},
{"id":"load-09","topic":"loading-performance","q":"How does cold weather typically affect drone battery performance?","options":["Voltage sag and reduced capacity shorten flight time","Capacity improves in cold air","There is no effect","Cold prevents overcharging"],"answer":0,"exp":"Cold slows the chemical reaction in lithium cells: expect voltage sag, shorter flights, and possible sudden capacity drops. Pre-warm packs and hover to warm them gently.","ref":"FAA Remote Pilot Study Guide; manufacturer guidance"},
{"id":"load-10","topic":"loading-performance","q":"Loading an aircraft so its CG sits at the aft limit tends to make it:","options":["More stable in gusts","Increasingly nose-heavy during landing approaches","Less stable and harder to recover from upsets","Fly with greater range"],"answer":2,"exp":"An aft CG reduces longitudinal stability. For any aircraft — manned or unmanned — recovery from a departure becomes harder as CG moves aft.","ref":"PHAK ch. 10 concepts"},
{"id":"ops-01","topic":"operations","q":"What is the antidote for the hazardous attitude of ANTI-AUTHORITY ('Don't tell me what to do')?","options":["Not so fast — think first","Taking chances is foolish and rarely pays off","Follow the rules — they are usually right","It could happen to me"],"answer":2,"exp":"Each hazardous attitude has a memorized antidote. Anti-authority is countered with 'Follow the rules. They are usually right.'","ref":"FAA Remote Pilot Study Guide; PHAK ch. 2"},
{"id":"ops-02","topic":"operations","q":"What is the antidote for IMPULSIVITY ('Do it quickly')?","options":["Follow the rules — they are usually right","Not so fast — think first","I'm not helpless","It could happen to me"],"answer":1,"exp":"Impulsivity is countered by deliberately slowing down: 'Not so fast. Think first.'","ref":"FAA Remote Pilot Study Guide; PHAK ch. 2"},
{"id":"ops-03","topic":"operations","q":"What is the antidote for INVULNERABILITY ('It won't happen to me')?","options":["Not so fast — think first","It could happen to me","Follow the rules","Taking chances is foolish"],"answer":1,"exp":"Believing accidents only happen to others is countered with 'It could happen to me.'","ref":"FAA Remote Pilot Study Guide; PHAK ch. 2"},
{"id":"ops-04","topic":"operations","q":"What is the antidote for MACHO ('I can do it')?","options":["I'm not helpless","It could happen to me","Taking chances is foolish","Follow the rules — they are usually right"],"answer":2,"exp":"The show-off attitude is countered with 'Taking chances is foolish.'","ref":"FAA Remote Pilot Study Guide; PHAK ch. 2"},
{"id":"ops-05","topic":"operations","q":"What is the antidote for RESIGNATION ('What's the use?')?","options":["Not so fast — think first","Follow the rules","I'm not helpless — I can make a difference","It could happen to me"],"answer":2,"exp":"Resignation is countered with 'I'm not helpless. I can make a difference.'","ref":"FAA Remote Pilot Study Guide; PHAK ch. 2"},
{"id":"ops-06","topic":"operations","q":"The IMSAFE checklist helps a pilot self-assess fitness to operate. What does it stand for?","options":["Inspection, Maintenance, Safety, Airspace, Flight plan, Emergency","Illness, Medication, Stress, Alcohol, Fatigue, Emotion","Instruments, Meteorology, Systems, Airframe, Fuel, Electronics","Identify, Measure, Set, Act, Fly, Evaluate"],"answer":1,"exp":"IMSAFE = Illness, Medication, Stress, Alcohol, Fatigue, Emotion — a personal go/no-go checklist before any operation.","ref":"FAA Remote Pilot Study Guide; PHAK ch. 2"},
{"id":"ops-07","topic":"operations","q":"Crew Resource Management (CRM) is best defined as:","options":["A checklist-reading method","A radio phraseology standard","Effective use of ALL available resources — people, hardware, and information","A maintenance scheduling system"],"answer":2,"exp":"CRM means integrating your crew (VOs, camera operators), equipment, and information sources to maximize safety — it applies to sUAS crews, not just airliners.","ref":"FAA Remote Pilot Study Guide"},
{"id":"ops-08","topic":"operations","q":"Situational awareness is best described as:","options":["Knowing only your GPS position","Watching the aircraft at all times","Reading back all radio calls","Accurate perception of all factors and conditions affecting flight safety"],"answer":3,"exp":"It covers the aircraft, environment, people, and time — the four risk elements — not just where the drone is right now.","ref":"FAA Remote Pilot Study Guide"},
{"id":"ops-09","topic":"operations","q":"A crew member is dizzy and tingling after breathing rapidly during a stressful launch. The best response to this hyperventilation is to:","options":["Breathe faster and deeper","Administer supplemental oxygen","Consciously slow the breathing rate — talking aloud or breathing into a bag helps","Call EMS immediately in every case"],"answer":2,"exp":"Hyperventilation flushes too much CO2. Slowing the breathing rate restores the balance; symptoms then resolve.","ref":"FAA Remote Pilot Study Guide; AIM ch. 8 concepts"},
{"id":"ops-10","topic":"operations","q":"Before operating after taking an over-the-counter medication, you should:","options":["Fly anyway — only prescription drugs matter","Check the label and side effects, and do not operate if it may impair you","Halve the dose","Rely on a strong cup of coffee to fully offset any drowsiness the medication causes"],"answer":1,"exp":"Many OTC antihistamines and cold medicines impair judgment and reaction time. Self-grounding is the pilot's responsibility.","ref":"14 CFR 107.17; FAA Remote Pilot Study Guide"},
{"id":"ops-11","topic":"operations","q":"Which statement about stress is most accurate?","options":["It improves focus in all situations","It only matters when stress reaches immediately life-threatening levels","It vanishes once the flight begins","Its effects are cumulative and can degrade judgment and performance"],"answer":3,"exp":"Stress from work, life, and the operation itself stacks up and narrows attention — a core ADM concept on the exam.","ref":"FAA Remote Pilot Study Guide"},
{"id":"ops-12","topic":"operations","q":"The most effective daytime technique for scanning for other aircraft is:","options":["One continuous sweep of the horizon","A systematic series of short, regularly spaced eye movements in roughly 10° segments","Staring at a fixed point ahead","Relying on peripheral vision alone"],"answer":1,"exp":"Eyes detect motion poorly while moving. Short fixations across 10° blocks let each segment come into focus.","ref":"FAA Remote Pilot Study Guide; AIM 8-1-6 concepts"},
{"id":"ops-13","topic":"operations","q":"Which statement about the preflight crew briefing is correct?","options":["It is optional for a crew of two","It is required only for night operations","It should happen only after an incident","It should assign roles, communication procedures, and contingencies before flight"],"answer":3,"exp":"107.49 requires ensuring all persons involved know their roles, emergency procedures, and how the crew will communicate — before takeoff.","ref":"14 CFR 107.49"},
{"id":"ops-14","topic":"operations","q":"What maintenance standard does Part 107 set for small unmanned aircraft?","options":["An FAA annual inspection","A 100-hour inspection by a mechanic","Keeping the aircraft in a condition for safe operation, checked before each flight","A notarized maintenance logbook reviewed and stamped annually by an FAA-certificated mechanic"],"answer":2,"exp":"There is no formal inspection regime; the RPIC must not operate an sUAS unless it is in a condition for safe operation, verified preflight.","ref":"14 CFR 107.15, 107.49"},
{"id":"ops-15","topic":"operations","q":"You notice smoke from the battery compartment during flight over a work site. The best course of action is to:","options":["Climb to blow out the flames","Continue the mission while monitoring the temperature readout closely","Switch to the backup battery in flight","Land as soon as safely possible, away from people"],"answer":3,"exp":"A thermal-runaway battery can fail totally within seconds. Get the aircraft on the ground clear of people and property immediately.","ref":"FAA Remote Pilot Study Guide; ADM"},
{"id":"ops-16","topic":"operations","q":"Regarding lost-link (loss of control signal), the remote pilot should:","options":["Know the aircraft's programmed lost-link behavior before flight","Assume the aircraft will always crash","Treat it as a reportable accident in every case","Wait indefinitely for reconnection before acting"],"answer":0,"exp":"Preflight planning includes knowing exactly what the aircraft will do on lost link (RTH altitude, hover time, land) and confirming those settings fit the site.","ref":"14 CFR 107.49; ACS UA.V"},
{"id":"ops-17","topic":"operations","q":"Your drone stops responding and drifts toward a crowded street (a flyaway). You should:","options":["Do nothing — flyaways are unavoidable","Follow your flyaway procedure, alert your crew, and warn bystanders if possible","Power off the controller and go home","Pursue the aircraft in your car"],"answer":1,"exp":"Execute the emergency procedure (regain link, activate failsafe), use your crew, and mitigate risk to people. Afterward, evaluate whether 107.9 reporting applies.","ref":"ACS UA.V; 14 CFR 107.9, 107.21"},
{"id":"ops-18","topic":"operations","q":"On the CTAF you hear: 'Hartsville traffic, Cessna 4-1-2, entering left downwind, runway one-eight.' This tells you:","options":["The position and intention of manned traffic near a non-towered airport","A control tower instruction that requires an immediate acknowledgment from you","An aircraft declaring an emergency","You are cleared to launch"],"answer":0,"exp":"Self-announced position reports on the CTAF are your main tool for anticipating manned traffic near non-towered fields — drones listen, they do not need to transmit.","ref":"FAA Remote Pilot Study Guide"},
{"id":"ops-19","topic":"operations","q":"If GPS signal degrades during a flight in a tight urban canyon, you should:","options":["Ignore it — GPS always recovers","Climb steeply to regain signal","Be prepared to fly in manual/attitude mode and consider landing","Immediately trigger return-to-home and let the automation handle everything"],"answer":2,"exp":"GPS-degraded drones drift. Be ready for manual control, keep visual contact, and land if positioning is unreliable. Blind RTH near obstacles can cause a collision.","ref":"ACS UA.V; manufacturer guidance"},
{"id":"ops-20","topic":"operations","q":"Your drone has no Category rating for operations over people. A crowd starts gathering under your flight path. You should:","options":["Continue as long as you remain above 100 ft AGL over the crowd","Speed up to spend less time overhead","Reposition or land so you are no longer over people","Do nothing — brief overflight is permitted"],"answer":2,"exp":"Without Category 1-4 eligibility, sustained flight over people not directly participating is prohibited — move the operation or pause until the area clears.","ref":"14 CFR 107.39"},
{"id":"ops-21","topic":"operations","q":"Where must your remote pilot certificate be during operations?","options":["At home in a safe place","Available for mailing to the FAA within 72 hours if requested","Digital copies are prohibited","Easily accessible to you during all sUAS operations"],"answer":3,"exp":"The certificate must be easily accessible during operations — physically or, practically, on your person — and presented on request.","ref":"14 CFR 107.7"},
{"id":"ops-22","topic":"operations","q":"While filming near a small airport in Class G airspace, a helicopter enters the traffic pattern. Part 107 requires that you:","options":["Not interfere with airport operations or traffic patterns, yielding right of way","Contact the helicopter on the radio","Land immediately and end all operations for the day","Climb above the pattern altitude"],"answer":0,"exp":"You may operate in Class G near an airport, but 107.43 and 107.37 require staying clear of patterns and yielding to all manned aircraft.","ref":"14 CFR 107.37, 107.43"},
{"id":"ops-23","topic":"operations","q":"Which is the only real remedy for fatigue?","options":["Strong coffee","Fresh air at the flight site","Adequate sleep","Willpower and experience"],"answer":2,"exp":"Stimulants mask symptoms briefly, but only sleep restores performance — fatigue degrades reaction time and judgment much like alcohol.","ref":"FAA Remote Pilot Study Guide"},
{"id":"ops-24","topic":"operations","q":"Prior to flight, the remote pilot in command must assess the operating environment, including:","options":["Local weather conditions, local airspace, and any ground hazards","Only the battery level","Only the official TAF forecast at the nearest Class B international airport","Nothing, if the flight is under 15 minutes"],"answer":0,"exp":"107.49 requires assessing weather, airspace and flight restrictions, people and property on the ground, and other ground hazards before every flight.","ref":"14 CFR 107.49(a)"},
{"id":"ops-25","topic":"operations","q":"During takeoff and landing — the most critical phases — the crew should:","options":["Chat to stay relaxed","Minimize non-essential conversation and distractions","Play the mission soundtrack","Rotate crew roles between positions to build practice reps"],"answer":1,"exp":"A 'sterile crew' discipline during critical phases keeps attention on the aircraft and its surroundings when risk is highest.","ref":"CRM concepts; FAA Remote Pilot Study Guide"},
{"id":"ops-26","topic":"operations","q":"For 'direct supervision' of a non-certificated person flying the drone, the RPIC must be able to:","options":["Monitor the aircraft's live video feed from a remote location","Take immediate control of the small unmanned aircraft","Sign the person's logbook","Stand within 10 feet of the person"],"answer":1,"exp":"Direct supervision means the RPIC can immediately take over the controls — the legal basis for letting a trainee or camera operator fly.","ref":"14 CFR 107.12, 107.19"},
{"id":"night-01","topic":"night-operations","q":"For night operations under Part 107, the anti-collision lighting must be visible for at least:","options":["1 statute mile, steady burning","3 statute miles, with a flash rate sufficient to avoid a collision","5 statute miles, any color","No lighting is required if a visual observer is used"],"answer":1,"exp":"Night ops require anti-collision lighting visible for 3 SM with an adequate flash rate. Standard consumer position lights usually do not qualify by themselves.","ref":"14 CFR 107.29"},
{"id":"night-02","topic":"night-operations","q":"In the continental US, civil twilight is generally the period:","options":["30 minutes before official sunrise and 30 minutes after official sunset","1 full hour before official sunrise and 1 full hour after official sunset","From sunset until sunrise","Only defined in summer months"],"answer":0,"exp":"Civil twilight spans roughly 30 minutes around sunrise/sunset in the lower 48 (Alaska uses a different definition).","ref":"14 CFR 107.29"},
{"id":"night-03","topic":"night-operations","q":"To operate during civil twilight, a small UA must have:","options":["No special equipment","Standard factory position lights on the aircraft only","Anti-collision lighting visible for 3 statute miles","A landing light"],"answer":2,"exp":"The same 3-SM anti-collision lighting rule covers both civil twilight and night operations.","ref":"14 CFR 107.29"},
{"id":"night-04","topic":"night-operations","q":"Before flying at night under the current rules, a remote pilot must have:","options":["A 107.29 waiver (still required today)","An instrument rating","Completed the updated initial knowledge test or the current online recurrent training","Nothing — there are no prerequisites"],"answer":2,"exp":"Since April 21, 2021, night flight is a standard privilege for pilots who completed the updated test/training, with proper anti-collision lighting.","ref":"14 CFR 107.29; 2021 final rule"},
{"id":"night-05","topic":"night-operations","q":"To best detect a dim object at night, you should:","options":["Stare directly at the object","Close one eye to sharpen focus","Scan rapidly back and forth across it","Look slightly off-center (about 5-10°) so the rod cells can detect it"],"answer":3,"exp":"Rods — the night-vision cells — sit outside the central fovea, so off-center viewing reveals dim objects that vanish when stared at directly.","ref":"FAA Remote Pilot Study Guide; AIM 8-1-6 concepts"},
{"id":"night-06","topic":"night-operations","q":"How long does it typically take the eyes to fully adapt to darkness, and what resets that adaptation?","options":["About 30 minutes; exposure to bright light resets it","About 5 minutes; nothing resets it","About 2 hours; only exposure to direct sunlight can reset it","Adaptation is instantaneous"],"answer":0,"exp":"Full rod adaptation takes roughly 30 minutes, and one glance at a bright white light — headlights, a phone screen — can undo it.","ref":"FAA Remote Pilot Study Guide"},
{"id":"night-07","topic":"night-operations","q":"Anti-collision lighting is required during which operating periods?","options":["Night only","Civil twilight and night operations","All operations, day and night","Night operations conducted in Class G airspace only"],"answer":1,"exp":"Both civil twilight and night operations require the 3-SM anti-collision lighting; daytime flights do not.","ref":"14 CFR 107.29"},
{"id":"rid-01","topic":"remote-id","q":"What are the three ways to comply with the Remote ID rule?","options":["A Standard Remote ID drone, a broadcast module, or flying at a FRIA","Registration, insurance, and a waiver","A transponder, ADS-B Out, and radar contact","Filing a flight plan before each mission"],"answer":0,"exp":"Compliance paths: built-in Standard Remote ID, an add-on broadcast module, or flying without RID only inside an FAA-Recognized Identification Area.","ref":"14 CFR Part 89"},
{"id":"rid-02","topic":"remote-id","q":"A drone using a Remote ID broadcast MODULE (instead of built-in Standard RID) must be operated:","options":["Only in Class G uncontrolled airspace below 400 ft","Within visual line of sight at all times","Only below 200 ft AGL","Only during daylight"],"answer":1,"exp":"Module-equipped aircraft must stay within VLOS — one of the two key module limitations, along with registering the module's serial number.","ref":"14 CFR Part 89"},
{"id":"rid-03","topic":"remote-id","q":"What must be done with a broadcast module's serial number?","options":["Keep it strictly confidential for national security reasons","Etch it on the propellers","List it in the aircraft's FAA registration record","Nothing — it activates automatically"],"answer":2,"exp":"The module serial number must be entered into the registration (FAA DroneZone) of each aircraft it flies on.","ref":"14 CFR Part 89; FAA DroneZone guidance"},
{"id":"rid-04","topic":"remote-id","q":"A FRIA is best described as:","options":["A paid FAA fast-track authorization zone","An FAA-recognized area where drones may fly without any Remote ID equipment","Any private property with the owner's permission","A frequency reserved for drone telemetry"],"answer":1,"exp":"FAA-Recognized Identification Areas — typically requested by community organizations and schools — are the only places non-RID aircraft may fly, within their boundaries and VLOS.","ref":"14 CFR Part 89"},
{"id":"rid-05","topic":"remote-id","q":"Which data set does a Standard Remote ID drone broadcast?","options":["The pilot's name and home address","The remote pilot certificate number","The aircraft's complete maintenance history","Drone ID, drone location/altitude and velocity, control station location/altitude, time mark, and emergency status"],"answer":3,"exp":"Standard RID includes the CONTROL STATION location — one reason the FAA adopted it for security. It does not broadcast your name; the public sees only the ID string.","ref":"14 CFR Part 89"},
{"id":"rid-06","topic":"remote-id","q":"Remote ID applies to which aircraft?","options":["Only drones over 55 lb","All drones required to be registered — including every aircraft flown under Part 107","Only recreational drones","Only drones flying beyond visual line of sight"],"answer":1,"exp":"If registration is required, Remote ID applies. Part 107 aircraft must ALWAYS be registered regardless of weight, so they always need RID (or a FRIA).","ref":"14 CFR Part 89, Part 48"},
{"id":"rid-07","topic":"remote-id","q":"Since when has operator compliance with Remote ID been required?","options":["September 16, 2023","January 1, 2020","It is voluntary until 2030","Only after the next FAA rulemaking cycle"],"answer":0,"exp":"Operators have been required to comply since September 16, 2023 (the FAA's enforcement discretion period ended March 16, 2024).","ref":"14 CFR Part 89"},
{"id":"rid-08","topic":"remote-id","q":"How can you verify that your drone has Standard Remote ID?","options":["Ask the retailer","Check whether the aircraft weighs over 250 g","Look it up on the FAA's public Declaration of Compliance (DOC) list","Assume that any drone manufactured after January 2020 complies automatically"],"answer":2,"exp":"The FAA's DOC database lists compliant makes/models; most current mainstream drones comply via firmware, but verification is the pilot's responsibility.","ref":"FAA UAS Declaration of Compliance listing"}
];
